package com.tap_to_translate.snap_translate.hymt2.ocr;
import ai.onnxruntime.*;import android.graphics.Bitmap;import java.io.File;import java.nio.*;import java.util.*;
public final class OnnxRuntimeRtDetrInference implements RtDetrInference {
 private static final int S=640,P=S*S;private final OrtEnvironment env;private final OrtSession session;private final String imageName,sizeName;private final int[] pixels=new int[P];private final float[] values=new float[P*3];private final FloatBuffer image=ByteBuffer.allocateDirect(P*12).order(ByteOrder.nativeOrder()).asFloatBuffer();private final LongBuffer size=ByteBuffer.allocateDirect(16).order(ByteOrder.nativeOrder()).asLongBuffer();private boolean closed;
 public OnnxRuntimeRtDetrInference(File model)throws OrtException{if(model==null||!model.isFile())throw new IllegalArgumentException("RT-DETR model missing");env=OrtEnvironment.getEnvironment();OrtSession.SessionOptions o=new OrtSession.SessionOptions();try{o.setIntraOpNumThreads(Math.max(1,Math.min(4,Runtime.getRuntime().availableProcessors())));o.setInterOpNumThreads(1);o.setOptimizationLevel(OrtSession.SessionOptions.OptLevel.ALL_OPT);session=env.createSession(model.getAbsolutePath(),o);}finally{o.close();}Set<String> names=session.getInputNames();if(names.size()<2){session.close();throw new IllegalStateException("RT-DETR requires two inputs");}imageName=names.contains("images")?"images":names.iterator().next();sizeName=names.contains("orig_target_sizes")?"orig_target_sizes":names.stream().filter(n->!n.equals(imageName)).findFirst().orElseThrow();}
 public synchronized RtDetrInferenceOutput run(Bitmap src)throws Exception{if(closed)throw new IllegalStateException("closed");if(src==null||src.isRecycled())throw new IllegalArgumentException("bitmap");Bitmap scaled=src.getWidth()==S&&src.getHeight()==S?src:Bitmap.createScaledBitmap(src,S,S,true);try{scaled.getPixels(pixels,0,S,0,0,S,S);for(int i=0;i<P;i++){int c=pixels[i];values[i]=((c>>16)&255)/255f;values[P+i]=((c>>8)&255)/255f;values[2*P+i]=(c&255)/255f;}image.clear();image.put(values);image.flip();size.clear();size.put(src.getWidth()).put(src.getHeight());size.flip();try(OnnxTensor a=OnnxTensor.createTensor(env,image,new long[]{1,3,S,S});OnnxTensor b=OnnxTensor.createTensor(env,size,new long[]{1,2})){Map<String,OnnxTensor> in=new HashMap<>();in.put(imageName,a);in.put(sizeName,b);try(OrtSession.Result r=session.run(in)){if(r.size()<3)throw new IllegalStateException("RT-DETR outputs missing");return new RtDetrInferenceOutput(labels(r.get(0).getValue()),boxes(r.get(1).getValue()),scores(r.get(2).getValue()));}}}finally{if(scaled!=src&&!scaled.isRecycled())scaled.recycle();}}
 private static long[] labels(Object v){if(v instanceof long[])return(long[])v;if(v instanceof long[][]){long[][]a=(long[][])v;if(a.length>0)return a[0];}throw new IllegalStateException("Unexpected labels tensor "+v.getClass());}
 private static float[][] boxes(Object v){if(v instanceof float[][][])return((float[][][])v)[0];if(v instanceof float[][])return(float[][])v;throw new IllegalStateException("Unexpected boxes tensor "+v.getClass());}
 private static float[] scores(Object v){if(v instanceof float[])return(float[])v;if(v instanceof float[][]){float[][]a=(float[][])v;if(a.length>0)return a[0];}throw new IllegalStateException("Unexpected scores tensor "+v.getClass());}
 public synchronized void close(){if(!closed){closed=true;try{session.close();}catch(OrtException ignored){}}}
}